"""P1 EDA: cohort composition and between-speaker heterogeneity of bona fide scores.

Uses only cohorts already exposed in Studies 1-2 (no speaker of the frozen speakercal split).
Descriptive; the score panel is post-hoc. Refuses to overwrite its output directory.
"""
import csv, json, hashlib, collections
from pathlib import Path
import numpy as np
import matplotlib; matplotlib.use('Agg')
import matplotlib.pyplot as plt
R = Path(__file__).resolve().parents[1]; A = R / 'results/asvspoof5_adaptation_v1'; C = R / 'results/asvspoof5_selfcal_v1'; O = R / 'results/p1_eda_v1'; P = R / 'paper/p1'
SR = 16000
sha = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()
read = lambda p: list(csv.DictReader(open(p)))
O.mkdir(exist_ok=False)
man = read(A / 'manifest.csv'); fr = {r['record_id']: int(r['frames']) for r in read(A / 'audio_audit_rows.csv')}
sman = read(C / 'manifest.csv'); sfr = {r['record_id']: int(r['frames']) for r in read(C / 'audio_audit_rows.csv')}
split = {r['speaker_id'] for r in read(R / 'results/speakercal_split_v1/split.csv')}
def row(name, recs, frames, note):
    spk = {r['speaker_id'] for r in recs}; assert not spk & split
    bona = [r for r in recs if r['label'] == 'bonafide']; spoof = [r for r in recs if r['label'] != 'bonafide']
    per = collections.Counter(r['speaker_id'] for r in bona); d = np.array([frames[r['record_id']] / SR for r in bona])
    return dict(cohort=name, speakers=len(spk), bona_fide=len(bona), bona_per_speaker=f'{min(per.values())}-{max(per.values())}', spoof=len(spoof),
                attacks=len({r['attack'] for r in spoof}), bona_duration_s_median=float(np.median(d)), bona_duration_s_q1=float(np.quantile(d, .25)), bona_duration_s_q3=float(np.quantile(d, .75)), note=note)
ev = [r for r in man if r['role'] == 'evaluation']
rows = [row('Study 1 adaptation', [r for r in man if r['role'] == 'adaptation'], fr, 'development set, unencoded'),
        row('Study 1 calibration', [r for r in man if r['role'] == 'calibration'], fr, 'development set, unencoded'),
        row('Study 1 evaluation (unencoded)', [r for r in ev if r['codec'] == '-'], fr, 'evaluation set'),
        row('Study 1 evaluation (encoded)', [r for r in ev if r['codec'] != '-'], fr, 'evaluation set; same 60 speakers'),
        row('Study 2 confirmation', sman, sfr, 'development set, unencoded; 20 enrollment + 30 test per speaker')]
with (O / 'cohorts.csv').open('x', newline='') as f: w = csv.DictWriter(f, fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
# Between-speaker share of bona fide score variance (one-way ICC) on the Study 2 cohort, all 20 models
z = np.load(R / 'results/selfcal_posthoc_v1/b1_arrays.npz', allow_pickle=True); s = np.concatenate([z['enrollment'], z['test_bona']], 1)  # (60, 50, 20)
names = {int(r['index']): (r['family'], r['model']) for r in read(R / 'results/selfcal_posthoc_v1/b1_models.csv')}
k = s.shape[1]; msb = k * s.mean(1).var(0, ddof=1); msw = s.var(1, ddof=1).mean(0); icc = (msb - msw) / (msb + (k - 1) * msw)
ic = [dict(family=names[m][0], model=names[m][1], icc_bona_fide=float(icc[m]), tied_fraction=float(1 - len(np.unique(s[:, :, m])) / s[:, :, m].size)) for m in range(s.shape[2])]
with (O / 'icc.csv').open('x', newline='') as f: w = csv.DictWriter(f, fieldnames=list(ic[0])); w.writeheader(); w.writerows(ic)
# Figure: per-speaker bona fide score spread for the two original checkpoints
BLUE, INK, MUTED = '#2a78d6', '#1f1f1d', '#5f5e58'
plt.rcParams.update({'font.family': 'serif', 'font.size': 8, 'axes.edgecolor': MUTED, 'axes.labelcolor': INK, 'xtick.color': MUTED, 'ytick.color': MUTED, 'axes.spines.top': False, 'axes.spines.right': False})
fig, axes = plt.subplots(1, 2, figsize=(7.0, 2.5))
for ax, fam, lab in zip(axes, ('aasist', 'xlsr_lcnn'), ('(a) AASIST, original checkpoint', '(b) XLSR-LCNN, original checkpoint')):
    m = next(i for i, v in names.items() if v == (fam, 'original')); v = s[:, :, m]; o = np.argsort(np.median(v, 1)); v = v[o]; x = np.arange(len(v))
    ax.vlines(x, v.min(1), v.max(1), color='#c9c8c0', lw=0.8, zorder=1)
    ax.vlines(x, np.quantile(v, .25, 1), np.quantile(v, .75, 1), color=BLUE, lw=2, zorder=2)
    ax.scatter(x, np.median(v, 1), s=7, color=INK, zorder=3)
    t = np.sort(z['enrollment'][:, :, m].ravel())[59]; ax.axhline(t, color=MUTED, lw=0.8, ls='--', zorder=0)
    ax.annotate('pooled 5% threshold', (0.99, t), xycoords=('axes fraction', 'data'), xytext=(0, 3), textcoords='offset points', ha='right', fontsize=7, color=MUTED)
    ax.set_title(f'{lab} (ICC {icc[m]:.2f})', fontsize=8, loc='left', color=INK); ax.set_xlabel('Speaker (sorted by median score)'); ax.set_xticks([])
axes[0].set_ylabel('Bona fide score (logit margin)')
fig.tight_layout(w_pad=2.0); fig.savefig(P / 'figs/fig_eda.png', dpi=300); fig.savefig(O / 'fig_eda.png', dpi=300)
L = ['% Generated by scripts/p1_eda.py from results/p1_eda_v1/cohorts.csv. Do not edit by hand.', r'\begin{tabular}{lrrrrrl}', r'\toprule', r'Cohort & Speakers & Bona fide & Per speaker & Spoofed & Attacks & Duration, s (median [IQR]) \\', r'\midrule']
for r in rows: L.append(f"{r['cohort']} & {r['speakers']} & {r['bona_fide']:,} & {r['bona_per_speaker'].replace('-', '--') if len(set(r['bona_per_speaker'].split('-'))) > 1 else r['bona_per_speaker'].split('-')[0]} & {r['spoof']:,} & {r['attacks']} & {r['bona_duration_s_median']:.1f} [{r['bona_duration_s_q1']:.1f}, {r['bona_duration_s_q3']:.1f}] \\\\".replace(',', '{,}').replace('[', '$[$').replace(']', '$]$').replace('{,} ', ', '))
L += [r'\bottomrule', r'\end{tabular}']; (P / 'tables/tab_eda.tex').write_text('\n'.join(L) + '\n')
fams = collections.defaultdict(list)
for r in ic: fams[r['family']].append(r['icc_bona_fide'])
summ = dict(code_sha256=sha(__file__), intersection_with_frozen_speakercal_split=0, sample_rate_assumed=SR, icc_range={f: [min(v), max(v)] for f, v in fams.items()},
            icc_original={r['family']: r['icc_bona_fide'] for r in ic if r['model'] == 'original'}, inputs={str(p.relative_to(R)): sha(p) for p in (A / 'manifest.csv', A / 'audio_audit_rows.csv', C / 'manifest.csv', C / 'audio_audit_rows.csv', R / 'results/selfcal_posthoc_v1/b1_arrays.npz')})
json.dump(summ, open(O / 'summary.json', 'x'), indent=2)
for r in rows: print(r)
print(json.dumps({k: summ[k] for k in ('icc_range', 'icc_original')}, indent=1)); print((P / 'tables/tab_eda.tex').read_text())
